```openscad
// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 50;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;     // knuckle cylinder diameter
knuckle_z   = 3.5;   // knuckle axis height above bed
knuckle_n   = 5;     // number of segments along length
knuckle_r   = knuckle_d / 2;
knuckle_h   = 2;     // knuckle height above axis centre

// ---- Pin hole ----
pin_d       = 3;     // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;   // extension past cut faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (axis along X at y = 12.5)
        for (i = [0 : knuckle_n - 1]) {
            x0 = (i - (knuckle_n - 1)/2) * plate_len / knuckle_n;
            translate([x0 - eps, 12.5, knuckle_z])
                cylinder(r = knuckle_r, h = knuckle_h);
        }
    }

    // Pin hole through every knuckle along the X axis
    translate([-plate_len/2 - eps, 12.5, knuckle_z])
        cylinder(r = pin_d/2, h = plate_len + 2*eps);
}
