pin_d       = 3;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0, 2, 4])
            translate([knuckle_xs[i], plate_wid/2, 0])
                cylinder(d = knuckle_d, h = plate_thk + 0.01);
    }

    // Pin hole along X through every knuckle
    for (x = knuckle_xs)
        translate([x, plate_wid/2, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = plate_len + 2*eps, center = true);
}
