knuckle_d   = 6;    // knuckle cylinder diameter
knuckle_z   = 3;    // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments along length
knuckle_x0  = 0;    // first segment starts at x = 0
knuckle_r   = knuckle_d / 2;

// ---- Pin hole ----
pin_d       = 2;    // pin hole diameter
pin_h       = 0.5;  // extra length so cut passes through knuckles

// ---- Misc ----
eps         = 0.5;  // overlap for clean boolean cuts

difference() {
    union() {
        // Base plate, centred on origin in X/Y
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along +Y edge (segments 1 and 3)
        for (i = [0 : knuckle_n - 1]) {
            x_s = knuckle_x0 + i * plate_len / knuckle_n;
            x_e = x_s + plate_len / knuckle_n;
            if (i == 0 || i == knuckle_n - 1)  // 1st and 3rd segments
                translate([x_s, plate_wid / 2, 0])
                    cylinder(d = knuckle_d, h = plate_thk + eps, $fn = 64);
        }
    }

    // Pin hole along the knuckle axis (x, y = 15, z = 3)
    translate([knuckle_x0 - pin_h, plate_wid / 2, knuckle_z])
        cylinder(d = pin_d, h = plate_len + 2 * pin_h + eps, $fn = 64);
}
