// Spoked wheel for a small sample cart
// Flat part, printed lying on the bed, centred on origin

// ---------- Parameters ----------
thickness     = 5;    // wheel thickness (Z)
rim_od        = 80;   // rim outer diameter
rim_width     = 4;    // rim radial width
hub_d         = 16;   // hub diameter
axle_d        = 5;    // axle hole diameter
spoke_count   = 4;    // number of spokes
spoke_width   = 4;    // spoke width
spoke_start_angle = 0; // first spoke along +X

overlap = 0.5;        // spoke overlap into hub/rim for clean union
eps     = 0.5;        // cutter extension past faces
$fn     = 128;

// Derived
rim_id      = rim_od - 2 * rim_width;     // rim inner diameter (72)
spoke_r0    = hub_d / 2 - overlap;        // spoke inner end
spoke_r1    = rim_id / 2 + overlap;       // spoke outer end
spoke_len   = spoke_r1 - spoke_r0;

// ---------- Model ----------
difference() {
    union() {
        // Rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([spoke_r0, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps, $fn = 64);
}
