knuckle_z   = 4;    // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments
knuckle_x0  = 0;    // first segment start (x)
knuckle_pitch = plate_len / knuckle_n; // segment length = 15 mm

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past cut faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on the +Y edge (y = 15)
        for (i = [0 : knuckle_n - 1]) {
            translate([knuckle_x0 + i * knuckle_pitch - knuckle_d/2,
                       plate_wid/2,
                       knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 0.5);
        }
    }

    // Pin hole along the knuckle axis (x, y = 15, z = 4) through every knuckle
    translate([knuckle_x0 - eps, plate_wid/2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_n * knuckle_pitch + 2*eps);
}
