// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_z   = 3;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of equal segments along X
knuckle_r   = [1, 3, 5]; // segment indices (1-based) with knuckles

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
segment_len = plate_len / knuckle_n;   // 8 mm
y_knuckle   = plate_wid / 2;           // 12.5 mm

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1, 3, 5
        for (i = [0 : knuckle_n - 1]) {
            idx = i + 1;
            if (knuckle_r[i] != idx) continue;
            translate([(idx - 1) * segment_len - segment_len/2,
                       y_knuckle,
                       knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 0.01);
        }
    }

    // Pin hole along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        idx = i + 1;
        if (knuckle_r[i] != idx) continue;
        translate([(idx - 1) * segment_len - segment_len/2 - eps,
                   y_knuckle,
                       knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = segment_len + 2*eps);
    }
}
