// Star-shaped indexing wheel
// 5-pointed star plate with a centre hole

n_points  = 5;     // number of star points
r_outer   = 30;    // radius to outer points (mm)
r_inner   = 18;    // radius to inner points (mm)
thickness = 5;     // plate thickness (mm)
hole_d    = 6;     // centre hole diameter (mm)
eps       = 0.5;   // cut overlap past faces (mm)
$fn       = 96;    // curve resolution

// Star outline: alternate outer and inner vertices, first outer point on +X
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? r_outer : r_inner,
             a = i * 180 / n_points)
        [r * cos(a), r * sin(a)]
];

difference() {
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // centre through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}
