        // Knuckles on 1st, 3rd, 5th segments (centres at x = -24, 0, 24)
        for (i = [0 : 2]) {
            x_c = (i - 1) * plate_len / (knuckle_n - 1);
            translate([x_c, knuckle_y, knuckle_z])
                cylinder(r = knuckle_r, h = plate_thk + 0.5);
        }
    }

    // Pin hole along X axis through every knuckle
    for (i = [0 : 2]) {
        x_c = (i - 1) * plate_len / (knuckle_n - 1);
        translate([x_c, knuckle_y, knuckle_z])
            cylinder(r = pin_d / 2, h = plate_thk + 2 * eps, center = true);
    }
}
