// Star-shaped indexing wheel (8-pointed), flat plate printed lying on the bed

// ---------------- Parameters ----------------
n_points     = 8;    // number of star points
r_outer      = 40;   // radius to outer (tip) points, mm
r_inner      = 20;   // radius to inner (valley) points, mm
thickness    = 3;    // plate thickness, mm
hole_d       = 6;    // centre through-hole diameter, mm
cut_overlap  = 0.5;  // extra length on cutting shapes past faces, mm
$fn          = 96;   // facet count for curved shapes

// ---------------- Derived ----------------
step = 360 / (2 * n_points);   // angular step between consecutive outline vertices

// Outline vertices: alternate outer/inner, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? r_outer : r_inner,
             a = i * step)
        [r * cos(a), r * sin(a)]
];

// ---------------- Model ----------------
difference() {
    // Star plate
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Centre through-hole
    translate([0, 0, -cut_overlap])
        cylinder(d = hole_d, h = thickness + 2 * cut_overlap, $fn = 96);
}
