spoke_r1   = rim_ir + spoke_overlap; // spoke end radius
eps        = 0.5;                    // cut overshoot

difference() {
    union() {
        // Rim ring
        difference() {
            cylinder(h = wheel_thk, r = rim_r);
            translate([0, 0, -eps])
                cylinder(h = wheel_thk + 2 * eps, r = rim_ir);
        }

        // Hub
        cylinder(h = wheel_thk, r = hub_r);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([spoke_r0, -spoke_width / 2, 0])
                    cube([spoke_r1 - spoke_r0, spoke_width, wheel_thk]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(h = wheel_thk + 2 * eps, d = axle_d);
