// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;   // plate length along X
plate_wid   = 25;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle cylinder diameter
knuckle_z   = 4;    // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments
knuckle_x0  = 0;    // first segment start (X)
knuckle_pitch = plate_len / knuckle_n; // segment length = 20 mm

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle segments (1st and 3rd only)
        for (i = [0 : knuckle_n - 1]) {
            x_s = knuckle_x0 + i * knuckle_pitch;
            if (i == 0 || i == knuckle_n - 1)
                translate([x_s, plate_wid/2, 0])
                    cylinder(d = knuckle_d, h = plate_thk + 0.01);
        }
    }

    // Pin hole along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        x_c = x_s = knuckle_x0 + i * knuckle_pitch;
        translate([x_c, plate_wid/2, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_pitch + eps, center = true);
    }
}
