    union() {
        // Flat plate, centred in X and Y
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st and 3rd segments
        for (i = knuckle_segs)
            axis_cyl(seg_x0(i), seg_len, knuckle_d);
    }

    // Pin hole through every knuckle, slightly longer than each knuckle
    for (i = knuckle_segs)
        axis_cyl(seg_x0(i) - hole_ext, seg_len + 2 * hole_ext, pin_hole_d);
