// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;   // distance of outer points from centre (mm)
inner_r   = 20;   // distance of inner points from centre (mm)
points    = 5;    // number of points (outer = inner + 180 deg)
plate_t   = 4;    // plate thickness (mm)
hole_d    = 8;    // central through-hole diameter (mm)
eps       = 0.5;  // cut overshoot past faces (mm)

$fn = 96;

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    cube([outer_r, outer_r, plate_t]);
        }
    }

    // Inner points (concave corners), evenly spaced in angle
    for (i = [0 : points - 1]) {
        rotate([0, 0, (i + 0.5) * 360 / points])
            translate([inner_r, 0, 0])
                cube([inner_r, inner_r, plate_t + eps]);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
