    // Star plate resting on the bed
    linear_extrude(height = plate_thick)
        polygon(points = star_pts);

    // Central through-hole
    translate([0, 0, -cut_overlap])
        cylinder(d = hole_diameter,
                 h = plate_thick + 2 * cut_overlap,
                 $fn = fn_curves);
}
