block_h      = 25;    // overall height of the frustum
pocket_w     = 20;    // square pocket side length
pocket_depth = 8;     // depth of pocket from the top face
eps          = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------- Derived ----------
half_base = base_size / 2;
half_top  = top_size / 2;

// ---------- Model ----------
difference() {
    // Solid square frustum
    linear_extrude(height = block_h)
        polygon([
            [-half_base, -half_base],
            [ half_base, -half_base],
            [ half_base,  half_base],
            [-half_base,  half_base]
        ]);

    // Square pocket cut into the top face, centred
    translate([0, 0, block_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
