// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part_t

$fn = 128;

// --- Dimensions (mm) ---
part_t      = 6;    // part thickness
outer_d     = 100;  // outer rim diameter
rim_w       = 6;    // rim width
hub_d       = 20;   // hub diameter
axle_d      = 6;    // axle hole diameter
spoke_w     = 5;    // spoke width
spoke_count = 4;    // number of spokes, evenly spaced
start_angle = 0;    // first spoke along +X axis

outer_r = outer_d / 2;
rim_o   = outer_r - rim_w / 2;   // outer radius of rim ring
hub_r   = hub_d / 2;

difference() {
    union() {
        // Outer rim ring
        cylinder(h = part_t, r = outer_r);
        // Hub
        cylinder(h = part_t, r = hub_r);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, start_angle + i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([outer_r, spoke_w, part_t]);
    }
    // Axle hole through hub centre
    translate([0, 0, -1])
        cylinder(h = part_t + 2, d = axle_d);
}
