        translate([0, 0, -0.01])
            cylinder(h = part_t + 0.01, r = hub_r);
        // Spokes from hub to rim
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_r - 0.01, -spoke_w / 2, 0])
                    cube([rim_r - hub_r + 0.01, spoke_w, spoke_t]);
    }
    // Axle hole through centre
    translate([0, 0, -eps])
        cylinder(h = part_t + 2 * eps, d = axle_d);
